#: Outlines whose ``र्`` is the IN-LINE half-form of ra rather than a repha,
#: and so must not be given the repha reordering marker -- see the module
#: docstring. The value is correct as it stands; only the reordering would
#: be wrong. Identified by geometry, not by hand: each of these is drawn in
#: the body of the line and carries a real advance width, where every repha
#: in these fonts sits above the headline with an advance of zero.
IN_LINE_RA_DIGESTS: frozenset[str] = frozenset(
    {
        "05c958432bf2766f",  # gid 226 र्  y 384..1320, advance 640
        "5316d94a5121c6d3",  # gid 226 र्  y 353..1320, advance 640
        "b9d361527566df9e",  # gid 226 र्  y 384..1320, advance 640
    }
)


def _has_reference_units_per_em(font: Any) -> bool:
    try:
        return bool(font["head"].unitsPerEm == REFERENCE_UNITS_PER_EM)
    except Exception:  # noqa: BLE001 - unreadable head means unknown geometry
        return False


def mangal_reference_map(
    font: Any, skip: Container[int] = frozenset()
) -> dict[int, str]:
    """``{CID: Unicode}`` for the glyphs of ``font`` this reference recognises.

    ``skip`` holds CIDs the caller has already resolved from the font itself.
    Those are authoritative -- the font's own ``cmap`` and ``GSUB`` beat any
    reference -- and skipping them also avoids hashing outlines whose answer is
    already known, which is most of them.

    Only glyphs whose outline this table carries are returned, so a font from
    another family yields an empty map without needing to be recognised or
    rejected by name. Same contract as
    :func:`likhit.extractors.kalimati_reference.kalimati_reference_map`.
    """

    if not _has_reference_units_per_em(font):
        return {}
    try:
        glyph_order = font.getGlyphOrder()
    except Exception:  # noqa: BLE001 - can't enumerate glyphs, so claim nothing
        return {}

    recovered: dict[int, str] = {}
    for gid, glyph_name in enumerate(glyph_order):
        if gid in skip:
            continue
        digest = outline_digest(font, glyph_name)
        if digest is None:
            continue
        value = OUTLINE_TO_UNICODE.get(digest)
        if value is not None:
            recovered[gid] = value
    return recovered


def mangal_in_line_ra_cids(font: Any, cids: Container[int]) -> set[int]:
    """Which of ``cids`` are the in-line ra, whose ``र्`` must not be reordered.

    Pass only the CIDs whose recovered value begins with ``ra + virama`` -- at
    most a handful per font -- so this costs a few extra outline hashes rather
    than a second pass over the whole glyph order.

    Returns an empty set for a font this reference does not recognise, which is
    the same "claim nothing" default as :func:`mangal_reference_map`.
    """

    if not _has_reference_units_per_em(font):
        return set()
    try:
        glyph_order = font.getGlyphOrder()
    except Exception:  # noqa: BLE001 - can't enumerate glyphs, so claim nothing
        return set()

    return {
        gid
        for gid, glyph_name in enumerate(glyph_order)
        if gid in cids and outline_digest(font, glyph_name) in IN_LINE_RA_DIGESTS
    }
